pub enum AssetTpslPriceWarningLeg {
    Tp,
    Sl,
}

#[derive(Debug, Clone, PartialEq)]
pub enum AssetTpslUxEvent {
    /// Validation passed, order params ready for submission
    OrderParamsReady {
        tp_trigger_px: Option<String>,
        tp_trigger_px_type: Option<String>,
        tp_ord_px: Option<String>,
        sl_trigger_px: Option<String>,
        sl_trigger_px_type: Option<String>,
        sl_ord_px: Option<String>,
        amount: String,
        side: OKTSide,
        inst_id: String,
        /// BUG B (2026-07-02): strategy order type for
        /// `/priapi/v5/trade/order-algo`. `"oco"` when both TP and SL legs are
        /// present, `"conditional"` for a single leg. Rust-owned decision
        /// (native `isStrategyOco`); Kotlin must set the order-algo ordType from
        /// this value, not re-derive it.
        ord_type: String,
    },
    /// Validation failed
    ValidationError {
        error_type: String,
        message: String,
    },
    /// No TP or SL input configured
    NoInput,
    /// Trigger-price relationship warning. `side` and `invalid_leg` are
    /// Rust-owned facts; Native only renders the indicated invalid control.
    PriceRelationshipWarning {
        /// Legacy TP/SL direction-error CDKey with a nested localized
        /// `{value}` price-type parameter. Native must resolve this before
        /// passing it into the input widget.
        message: DisplayString,
        side: OKTSide,
        invalid_leg: AssetTpslPriceWarningLeg,
    },
    /// Strategy order placed successfully. `algo_id` is the created algo order id.
    OrderSuccess {
        algo_id: String,
    },
    /// Strategy order failed. `error_code` = backend sCode (or business code from a
    /// network error); `message` = backend sMsg; `frozen` routes an account-frozen
    /// code to the Kotlin `UnfreezeUtils` flow (no toast) — mirror
    /// `KLineAddAssetTpslUxEvent::AddFailed`.
    OrderFailed {
        error_code: String,
        message: String,
        frozen: bool,
    },
}

