/// UI events emitted by ContractChaseInteractor after order placement.
/// 
/// Rust determines success/failure/error type; Kotlin only does UI response.
#[derive(Debug, Clone, PartialEq)]
pub enum ContractChaseUiEvent {
    /// The attempt intentionally ended before IO because another notice owns the UI.
    OrderAttemptTerminated {
        attempt_id: u64,
        reason: ContractOrderAttemptTerminationReason,
    },
    /// Rust intercepted the order attempt; Native must present the equity-perp
    /// (TradFi SWAP) risk-disclosure sheet before the order proceeds (#3).
    ShowEquityPerpRiskDisclosure {
        attempt_id: u64,
        presentation_id: u64,
    },
    /// Rust intercepted the order attempt; Native must present the pre-market
    /// trading-notice sheet before the order proceeds (V1 T2).
    ShowPreMarketNotice {
        attempt_id: u64,
        presentation_id: u64,
    },
    /// Rust intercepted the order attempt; Native must present the rebase-contract
    /// trading-notice sheet before the order proceeds (V1 T2).
    ShowRebaseNotice {
        attempt_id: u64,
        presentation_id: u64,
    },
    /// Order placed successfully -- Kotlin: success toast + normalOrderSuccess + clearInput
    OrderSuccess {
        attempt_id: u64,
        algo_id: String,
    },
    /// Insufficient balance (sCode == "51008") -- Kotlin: toast + balance check + Grafana
    OrderInsufficientBalance {
        attempt_id: u64,
        inst_type: String,
        inst_id: String,
        error_msg: String,
        error_code: String,
    },
    /// Other failure -- Kotlin: toast + Grafana
    OrderFailed {
        attempt_id: u64,
        error_msg: String,
        error_code: String,
    },
    /// Ticker data updated -- Kotlin: read prices via getter methods
    TickerUpdated,
    /// Position data updated -- Kotlin: refresh close-available via showCloseAvailable()
    PositionUpdated,
    /// Max-available data loaded -- Kotlin: feed to RustBalanceLoader
    MaxAvailableLoaded {
        response: ContractMaxAvailResponse,
    },
    /// Max-available fetch failed -- Kotlin: notify RustBalanceLoader
    MaxAvailableFailed {
        error_message: String,
    },
    /// Pre-flight submit gate blocked (V1 base checkInputFocus): focus field + keyboard.
    ValidationBlocked {
        attempt_id: u64,
        focus_field: ContractInputFocusField,
        toast: Option<DisplayString>,
        corrected_value: Option<String>,
    },
    /// The "switch account mode & trade" upgrade CTA was tapped. Rust decided
    /// quick-vs-fullpage per the V1 `UpgradeForTradeBtnComponent.onClick` threshold
    /// (USDT-quoted + tradeable balance < 10000 -> Quick); Kotlin routes accordingly.
    OpenUpgradeAccountFlow {
        decision: UpgradeAccountFlowDecision,
    },
}

