#[derive(Debug, Clone, PartialEq)]
pub enum DexTpslUxEvent {
    /// State has been updated (leg added/removed/validated)
    StateUpdated,
    /// Create TPSL API succeeded — Kotlin MUST call either `submit_sign()` or
    /// `reset_submitting()` after receiving this event. Failing to do so will
    /// leave `is_submitting=true` and block further submissions.
    CreateTpslSuccess {
        contract_deployed: bool,
        uop_hash: String,
        server_option: String,
        pre_trade_id: String,
        /// Sign type from server: 1=Passkey, 2+=Session Key. Falls back to 1 if absent.
        sign_type: i32,
    },
    /// Modify TPSL API succeeded — same signing flow as create, but passkey uses
    /// the original order_id (NOT pre_trade_id).
    ModifyTpslSuccess {
        contract_deployed: bool,
        uop_hash: String,
        server_option: String,
        /// The original order ID passed to modify_tpsl — used for passkey submission
        order_id: String,
        /// Sign type from server: 1=Passkey, 2+=Session Key. Falls back to 1 if absent.
        sign_type: i32,
    },
    /// Modify TPSL API failed
    ModifyTpslError {
        error_code: String,
        error_msg: String,
    },
    /// Create TPSL API failed
    CreateTpslError {
        error_code: String,
        error_msg: String,
    },
    /// Submit sign (passkey) succeeded — order is finalized
    SubmitSignSuccess,
    /// Submit sign (passkey) failed
    SubmitSignError {
        error_code: String,
        error_msg: String,
    },
}

