/// FFI-compatible error type for use with OKRustFuture
/// Supports cancellation via OKCancellationError
#[derive(Debug, Clone, PartialEq)]
pub enum FFITradingError {
    NetworkError {
        http_status: i32,
        code: i32,
        error_message: String,
    },
    NoDataFound {
        error_message: String,
    },
    JSONParseError {
        error_message: String,
    },
    InvalidParameter {
        error_message: String,
    },
    /// Cancellation variant - required for `with_cancellation` support
    /// Using #[from] attribute automatically implements From<OKCancellationError>
    OperationCancelled(OKCancellationError),
    InternalError {
        error_message: String,
    },
}

