#[derive(Debug, Clone, PartialEq)]
pub enum PureEventDetailUxEvent {
    /// UP_DOWN instrument settled — native shows settled result dialog.
    UpDownSettlement {
        inst_id: String,
        outcome: String,
        settle_price: String,
        stk: String,
        exp_time: String,
        method: String,
        series_id: String,
    },
    /// ABOVE instruments settled (same seriesId + expTime batch).
    AboveSettlement {
        instruments: Vec<SettledInstrumentVo>,
    },
    /// Countdown hit 0 — widget-side countdown finished. Rust has already
    /// triggered `refresh_biz_data` (the sole rust-owned side of native
    /// `handleUpDownCountdownExpired`). Payload carries the fields needed by
    /// the Kotlin Fragment observer to route UI updates (chip → ended,
    /// top_price → ended, outcome banner) via the same Fragment-layer router
    /// pattern the sheet handlers use — `refresh_biz` is async so we can't rely
    /// on the Kotlin observer reading a freshly patched `state.top_price`;
    /// snapshot the raw instrument fields sync at emit time.
    CountdownExpired {
        inst_id: String,
        method: String,
        /// Instrument freq (e.g. "5MIN" / "HOUR" / "DAILY") — Kotlin passes to
        /// `EventContractTitleHelper.formatUpDownPeriodLabel(expTimeMs, freq)`
        /// which branches DAILY→"MMMd" vs HH:mm.
        freq: String,
        exp_time_ms: i64,
        /// `false` when outcome is not yet available (Kotlin shows settling).
        is_really_settled: bool,
        /// Positive-outcome flag; only meaningful when `is_really_settled = true`.
        is_rise: bool,
        /// Raw strike price (unformatted) — Kotlin passes to `showEndedOutcome`.
        stk: String,
        /// Raw settlement price (unformatted). Empty when not yet settled.
        settle_price: String,
    },
    /// First live period expired while user is on a different chip.
    ForegroundResumeRefresh,
    /// Current instrument expired during background.
    ResumeExpired {
        inst_id: String,
    },
    /// Toast message.
    ShowToast {
        message: String,
    },
    /// HIT — currently-viewed HIT instrument just settled (via WS push).
    /// Payload carries the raw fields needed by the Kotlin Fragment router
    /// to (1) swap to marketEventList and (2) flip TopPriceView / header /
    /// outcome banner to the ended-with-outcome state. Mirror Native
    /// `hitSettlementLiveData` (`EventContractDetailPresenter.settlementNotify`:206).
    HitCurrentSettled {
        inst_id: String,
        outcome: String,
        settle_price: String,
        stk: String,
        exp_time: String,
        series_id: String,
    },
}

