pub enum PureOrderDetailStrategyType {
    /// Normal limit / market order (V1 `OrderData.NORMAL_ORDER`).
    Normal,
    /// Strategy order (trigger / TPSL / conditional / OCO) — V1
    /// `OrderData.STRATEGY_ORDER` with a `TradeStrategyOrderData` payload.
    Strategy,
    /// Strategy pending order (move-order-stop / trailing-stop) — V1
    /// `OrderData.STRATEGY_ORDER` with a `StrategyPendingListResp` payload.
    /// Split from [`Self::Strategy`] because the move-stop detail row set
    /// (callback ratio / trigger / active price) comes from a different raw
    /// type (`StrategyPendingListRecord`) and builder
    /// (`StrategyPendingDetailBuilder`), mirroring V1's
    /// `convertStrategyOrderDetailCommon(data: StrategyPendingListResp, ...)`.
    StrategyPending,
    /// DDH (Delta Hedge) order branch — V1
    /// `TradeOrderData.category == "ddh"`.
    Ddh,
    /// Liquidation / ADL detail branch — V1
    /// `convertLiquidatedOrderDetailCommon` route.
    Liquidation,
}

/// Outbound events for `PureOrderDetailInteractor`.
/// 
/// Each `Load*` variant maps to one ItemBinder section on the V1
/// detail page so the Kotlin Fragment can keep the per-section adapter
/// state in sync without re-reading the whole `state()` snapshot.
#[derive(Debug, Clone, PartialEq)]
pub enum PureOrderDetailUxEvent {
    /// Generic toast (success / fail message routing).
    ShowToast {
        message: String,
    },
    /// Header (raw order JSON snapshot) is bound — Kotlin can render
    /// the `OrderDetailsHeaderItemBinder` / `OrderDetailsDealHeaderItemBinder`
    /// row immediately.
    HeaderBound {
        order_id: String,
        inst_type: String,
        inst_id: String,
        strategy_type: PureOrderDetailStrategyType,
    },
    /// Fills load started — Kotlin shows shimmer for the deal-list
    /// section.
    FillsLoadStarted,
    /// Fills load completed — `items` drives the
    /// `OrderDetailsDealItemBinder` adapter submit.
    FillsLoadCompleted {
        items: Vec<TradeFillsData>,
        has_more: bool,
    },
    /// Fills load failed — Kotlin shows error row.
    FillsLoadFailed {
        error: String,
    },
    /// Chase info load started (V1
    /// `TradeOrderDetailPresenter.getChaseOrderInfo`).
    ChaseInfoLoadStarted,
    /// Chase info load completed.
    ChaseInfoLoadCompleted {
        items: Vec<ChaseOrderInfo>,
    },
    /// Chase info load failed.
    ChaseInfoLoadFailed {
        error: String,
    },
    /// Force / liquidation detail load started.
    ForceDetailLoadStarted,
    /// Force / liquidation detail load completed.  Drives the
    /// `OrderDetailsLiquidationDescItemBinder` row.
    ForceDetailLoadCompleted {
        items: Vec<OrderForceDetail>,
    },
    /// Force / liquidation detail load failed.
    ForceDetailLoadFailed {
        error: String,
    },
    /// Native strategy-cancel warning. No cancel RPC starts before confirmation.
    RequireCancelConfirmation {
        kind: PureOrderDetailCancelConfirmation,
    },
    /// Cancel started (cancel button on detail page).
    CancelStarted,
    /// Cancel succeeded.
    CancelCompleted,
    /// Cancel failed.
    CancelFailed {
        error: String,
    },
}

