/// Request parameters for contract max available query
/// 
/// This is a business-level abstraction that captures the intent
/// of the query, which gets mapped to appropriate API parameters.
/// 
/// # Factory Functions
/// 
/// Use the factory functions to create requests for different order types:
/// - [`limit()`](Self::limit) - Limit orders
/// - [`market()`](Self::market) - Market orders
/// - [`chase_limit()`](Self::chase_limit) - Chase limit orders
/// - [`strategy()`](Self::strategy) - Strategy orders (trigger/TP-SL/trailing)
/// 
/// Note: Scaled orders do NOT call max available API.
#[derive(Debug, Clone, PartialEq)]
pub struct ContractMaxAvailRequest {
    /// Instrument ID (e.g., "BTC-USDT-SWAP", "BTC-USD-240329")
    pub inst_id: String,
    /// Trade mode (cross or isolated margin)
    pub trade_mode: OKTTradeMode,
    /// Order entrust type for categorization
    pub order_type: OKTOrderEntrustType,
    /// Position mode (net mode or long/short mode)
    pub position_mode: OKTPosMode,
    /// Trade side (buy or sell) - optional for most scenarios
    pub side: Option<OKTSide>,
    /// Whether this is a reduce-only order
    pub reduce_only: bool,
    /// Virtual-account identifier used only by the locked XPerp voucher panel.
    /// Ordinary contract max-available requests leave this unset.
    pub virtual_account_id: Option<String>,
    /// Order price
    pub price: Option<String>,
    /// Order size (conditionally required based on account config)
    pub size: Option<String>,
    /// PM+cross buy/sell-margin order size -> the API `sz` param. Under PM+cross the BE
    /// computes buySize/sellSize (the buy/sell margin) FROM `sz`; without it it returns "0"
    /// (panel showed "0 USDT"). Mirrors V1 `BaseBusinessFragment.getOrderSize` (isPmUnique-gated).
    /// Kept SEPARATE from `size` (which maps to buySz/sellSz for liq-price / increase-position)
    /// so this fix touches only the PM order panels — every non-PM path stays byte-identical.
    /// Populated only by the contract order-panel `fetch_max_available` (PM-gated via
    /// `pm_max_avail_sz`); None everywhere else.
    pub pm_margin_sz: Option<String>,
    /// Buy size for liquidation price estimation (or cost order)
    pub buy_size_for_liq_price: Option<String>,
    /// Sell size for liquidation price estimation (or cost order)
    pub sell_size_for_liq_price: Option<String>,
    /// Whether to enable spot hedging (for PM accounts)
    pub un_spot_offset: Option<bool>,
    /// Order IDs to exclude from available calculation
    pub exclude_order_id: Option<String>,
    /// Algo order IDs to exclude from available calculation
    pub exclude_algo_id: Option<String>,
    /// Order type string (e.g., "market" for market orders)
    /// Used for API request, automatically set by factory functions
    pub ord_type: Option<String>,
    /// Whether to include transfer capability in the response
    pub is_need_transfer: Option<bool>,
}

/// Response for contract max available query
/// 
/// Contains the calculated maximum available amounts and related data
/// for the specific trading scenario.
#[derive(Debug, Clone, PartialEq)]
pub struct ContractMaxAvailResponse {
    /// Available margin balance
    pub available: String,
    /// Loanable (borrowed) portion of `available`. Mirrors the raw BE
    /// `MaxAvailableResp.loan_available`; retained here (not dropped during mapping)
    /// so the account-mode quick-switch gate can compute V1's
    /// `available - loanAvailable < 10000` threshold from cached state.
    /// See `contract/common/orchestration/account_mode_gate.rs`.
    pub loan_available: String,
    /// Currency of the available balance
    pub available_currency: String,
    /// Maximum buy size (open long / buy)
    pub max_buy_size: String,
    /// Maximum sell size (open short / sell)
    pub max_sell_size: String,
    /// Current long position quantity
    pub long_position: String,
    /// Current short position quantity
    pub short_position: String,
    /// Closable long position quantity (position - pending close orders)
    pub long_available_close: String,
    /// Closable short position quantity (position - pending close orders)
    pub short_available_close: String,
    /// Estimated liquidation price for buy/long direction
    pub liq_price_buy: String,
    /// Estimated liquidation price for sell/short direction
    pub liq_price_sell: String,
    /// Price used for calculation (returned by API)
    pub px: String,
    /// Base currency max transferable (for coin-margined contracts)
    pub base_max: String,
    /// Quote currency max transferable (for USDT-margined contracts)
    pub quote_max: String,
    /// Original base currency max (without formatting, for strategy orders)
    pub origin_base_max: String,
    /// Original quote currency max (without formatting, for strategy orders)
    pub origin_quote_max: String,
    /// Buy order cost estimate (IMR + potential loss + estimated fee). Non-EEA buy value.
    pub buy_cost: String,
    /// Sell order cost estimate (IMR + potential loss + estimated fee). Non-EEA sell value.
    pub sell_cost: String,
    /// Buy IMR (initial margin + potential loss, EXCLUDING the estimated fee).
    /// EEA regular-panel buy value; empty when the backend omitted it (renders "--", NO Cost fallback).
    pub buy_imr: String,
    /// Sell IMR (initial margin + potential loss, EXCLUDING the estimated fee).
    /// EEA regular-panel sell value; empty when the backend omitted it (renders "--", NO Cost fallback).
    pub sell_imr: String,
    /// Estimated buy fee. Parsed only (retained as contract data); not surfaced for separate display.
    pub buy_fee: String,
    /// Estimated sell fee. Parsed only (retained as contract data); not surfaced for separate display.
    pub sell_fee: String,
    /// Original raw response (for debugging/extensions)
    pub raw_response: Option<String>,
    /// Pre-formatted available margin balance (e.g. "72892.93 USDT").
    pub available_display: String,
    /// Pre-formatted max buy size with unit (e.g. "346 zhang" for contracts, "346 shou" for TradFi).
    pub max_buy_display: String,
    /// Pre-formatted max sell size with unit.
    pub max_sell_display: String,
    /// Pre-formatted buy order cost/margin (e.g. "2.05 USDT").
    pub buy_cost_display: String,
    /// Pre-formatted sell order cost/margin (e.g. "0.00 USDT").
    pub sell_cost_display: String,
    /// Pure numeric available margin value (no unit, no separator).
    pub available_display_value: String,
    /// Pure numeric max buy size value.
    pub max_buy_display_value: String,
    /// Pure numeric max sell size value.
    pub max_sell_display_value: String,
    /// Pure numeric buy order cost/margin value.
    pub buy_cost_display_value: String,
    /// Pure numeric sell order cost/margin value.
    pub sell_cost_display_value: String,
    /// Unit symbol for size values (zhang / shou).
    pub size_display_unit: String,
    /// Unit symbol for margin/cost/available values (settle or ct_val ccy).
    pub margin_display_unit: String,
    /// Unit symbol for the cost/amount row (`buy_cost_display_value`/`sell_cost_display_value`).
    /// Defaults to `margin_display_unit` (amount-input mode -> the row shows a margin/cost).
    /// In cost-input mode the row shows the derived contract amount, so the Full-layout panels
    /// (limit/market/advanced) set it to `size_display_unit` via `format_response_display_with_row`.
    /// Kept out of `margin_display_unit` so the available/max-open rows keep the margin unit.
    pub cost_row_unit: String,
    /// PM(portfolio-margin)+cross: the max-buy/sell "size" row is really the buy/sell margin
    /// (coin unit) and the label flips to buy/sell margin (V1 isFutureSwapAssemblyCrossed).
    /// Set in `format_response_display`; read by `build_max_avail_loaded` for the label.
    pub is_pm_cross: bool,
}

