/// Complete instrument record for FFI - contains fields from all instrument types
/// 
/// This is a union type containing all fields from:
/// - SpotInstrument (67 fields)
/// - SwapInstrument (54 fields)
/// - FuturesInstrument (60 fields)
/// - OptionInstrument (50 fields)
/// 
/// - "SPOT"/"MARGIN": Use base_ccy, quote_ccy, coin_lever, etc.
/// - "SWAP": Use ct_val, ct_type, settle_ccy, etc.
/// - "FUTURES": Use exp_time, alias, next_settle_time, etc.
/// - "OPTION": Use opt_type, stk, etc.
#[derive(Debug, Clone, PartialEq)]
pub struct InstrumentRecord {
    pub inst_id: String,
    pub inst_type: String,
    pub inst_category: String,
    pub coin_name: String,
    pub id: String,
    pub tick_sz: String,
    pub lot_sz: String,
    pub min_sz: String,
    pub state: String,
    pub new_tag: String,
    pub new_label: String,
    pub online_time: String,
    pub list_time: String,
    pub list_stage: String,
    pub inst_family: String,
    pub iso_flag: String,
    pub lever: String,
    pub status: String,
    pub uly: String,
    pub enable_filter: bool,
    pub max_lmt_sz: String,
    pub max_mkt_sz: String,
    pub max_lmt_amt: String,
    pub max_mkt_amt: String,
    /// Base currency (Spot only, e.g., "BTC")
    pub base_ccy: String,
    /// Quote currency (Spot only, e.g., "USDT")
    pub quote_ccy: String,
    /// Coin leverage (Spot only)
    pub coin_lever: String,
    /// Pre-quote status (Spot only)
    pub pre_quote: String,
    /// Continuous auction status (Spot only)
    pub continuous: String,
    /// Display ID (Spot only)
    pub display_id: String,
    /// Display quote currency (Spot only)
    pub display_quote_ccy: String,
    /// Trade quote currency list (Spot only)
    pub trade_quote_ccy_list: Vec<String>,
    pub within_ten_mins_of_contract_generation: String,
    pub ten_mins_after_contract_generation: String,
    pub index_max_threshold_rate: String,
    pub price_limit_status: String,
    pub spot_lp_h1: String,
    pub spot_lp_h2: String,
    pub spot_lp_h3: String,
    pub spot_lp_j1: String,
    pub spot_lp_j2: String,
    /// Contract multiplier (Swap/Futures/Option)
    pub ct_mult: String,
    /// Contract type: linear/inverse (Swap/Futures/Option)
    pub ct_type: String,
    /// Contract value (Swap/Futures/Option)
    pub ct_val: String,
    /// Contract value currency (Swap/Futures/Option)
    pub ct_val_ccy: String,
    /// Settlement currency (Swap/Futures/Option)
    pub settle_ccy: String,
    /// Rule type (Swap/Futures)
    pub rule_type: String,
    /// Alias name (Futures/Option)
    pub alias: String,
    pub lp_x1: String,
    pub lp_x2: String,
    pub lp_y1: String,
    pub lp_y2: String,
    pub lp_z1: String,
    pub lp_z2: String,
    pub user_position_max_percent: String,
    pub user_position_max_value_usd: String,
    pub platform_side_position_max_value_usd: String,
    /// Platform open interest limit in USD (new modal)
    pub max_plat_oi_lmt: String,
    /// Platform open interest limit in base coin (new modal)
    pub max_plat_oi_coin_lmt: String,
    /// Expiration time (Futures/Option)
    pub exp_time: String,
    /// Expiry display flag (Futures only)
    pub expiry_display: String,
    /// Settlement close max threshold (Futures only)
    pub close_max_threshold_rate_week: String,
    /// Future settlement flag (Futures only)
    pub future_settlement: bool,
    /// Next settlement time (Futures only)
    pub next_settle_time: String,
    /// LP C parameters (Futures only)
    pub lp_c1: String,
    pub lp_c2: String,
    /// BE-provided lower price limit band (Swap/Futures); empty when absent.
    pub lower_price_limit_band: String,
    /// BE-provided higher price limit band (Swap/Futures); empty when absent.
    pub higher_price_limit_band: String,
    /// Option type: C=Call, P=Put (Option only)
    pub opt_type: String,
    /// Strike price (Option only)
    pub stk: String,
    /// TradFi: lot size standard (zhang per lot, e.g. "100"). Empty when the
    /// instrument is not part of the TradFi product line.
    pub lot_size_std: String,
    /// TradFi: price tick unit display (e.g. "USDT").
    pub price_tick_unit: String,
    /// TradFi: unit per lot display (e.g. "OZ").
    pub unit_per_lot: String,
    /// xStock: on-chain tokens per share for tokenized-stock SPOT pairs.
    /// Empty when the instrument is not a tokenized-stock SPOT pair.
    pub x_stock_multiplier: String,
    /// Spread width parameters (Option only)
    pub spread_width_obl_min_base_spread: String,
    pub spread_width_obl_delta_factor: String,
    pub px_limit_factor: String,
    pub mas_pa_delta_threshold: String,
    pub spread_width_obl_min_base_spread_v2: String,
    pub spread_width_obl_delta_factor_gt_haft_v2: String,
    pub spread_width_obl_delta_factor_lt_haft_v2: String,
    pub spread_width_obl_min_base_spread_v3: String,
    pub spread_width_obl_delta_factor_gt_haft_v3: String,
    pub spread_width_obl_delta_factor_lt_haft_v3: String,
    /// Prediction method: "PRICE_UP_DOWN" / "PRICE_ABOVE"
    pub method: String,
    /// Frequency: "FIVE_MIN" / "FIFTEEN_MIN" / "HOURLY" / "DAILY"
    pub freq: String,
    /// Series identifier, e.g. "BTC-UPDOWN-15MIN"
    pub series_id: String,
    /// Event identifier (only from WS, typically empty from HTTP)
    pub event_id: String,
    /// Settlement result: "UP"/"DOWN"/"YES"/"NO" (empty if not settled)
    pub outcome: String,
    /// Disputed flag: "1" (disputed) / "0" (not disputed)
    pub disputed: String,
    /// Share volume
    pub vol_share: String,
    /// Settlement price (populated by offlined API for ended instruments, empty for live)
    pub settle_price: String,
    /// Upper-bound strike price for BETWEEN-method events (empty for other
    /// methods). "INF" sentinel signals an unbounded upper edge — mirrors
    /// Kotlin `EventInstrument.capStk`.
    pub cap_stk: String,
}

