pub struct OKTDepthDisplayData {
    /// Formatted bid (buy) items, sorted by price descending.
    pub bids: Vec<OKTFormattedDepthItem>,
    /// Formatted ask (sell) items, sorted by price ascending.
    pub asks: Vec<OKTFormattedDepthItem>,
}

