/// Order count data for UI display
/// 
/// Aggregated order count data calculated from MainOrdPosModel.
/// Used to display count numbers on UI tabs and menus.
/// 
/// # Kotlin Mapping
/// 
/// This maps to Kotlin's `OrderPositionData`:
/// - `pos_total_amt` → `posTotalAmt`
/// - `pos_asset_amt` → `posAssetAmt`
/// - `normal_order_amt_data` → `normalOrderAmtData`
/// - `strategy_order_amt_data` → `strategyOrderAmtData`
#[derive(Debug, Clone, PartialEq)]
pub struct OrderCountData {
    /// Total position count (cross + isolated + virtual sub-accounts)
    pub pos_total_amt: String,
    /// Total asset (spot balance) count
    pub pos_asset_amt: String,
    /// Normal order amounts (limit/market/advanced/stop)
    pub normal_order_amt_data: NormalOrderAmtData,
    /// Strategy order amounts (stop/trigger/trailing)
    pub strategy_order_amt_data: StrategyOrderAmtData,
    /// DEX pending order count (market + limit, excludes TPSL)
    pub dex_pending_order_num: String,
    /// DEX TP/SL pending order count
    pub dex_tpsl_pending_order_num: String,
    /// Contract copy trading position count
    pub order_lead_amt: String,
    /// Spot copy trading position count
    pub spot_lead_amt: String,
    /// Current open split sub-position count. This is the server total, not the
    /// capped split-position detail-list size.
    pub split_pos_amt: String,
    /// Bot strategy order entries from algo-private-summary.
    /// Native side iterates this list to rebuild BotAmtData (countMap / pinCountMap).
    pub bot_amt_list: Vec<BotAmtEntry>,
}

/// Order count data for tab badges — a flat UniFFI-exportable struct.
