pub struct PureEventLimitState {
    pub instrument: EventInstrumentConfigVo,
    pub side: String,
    pub direction: String,
    pub is_open_close_mode: bool,
    pub is_double_position_mode: bool,
    /// Account gating for the place-order button (Native updatePlaceOrderButton).
    /// Sourced in start() from CoreUserManager::is_login /
    /// trade_setting.is_trade_account. Mirror margin-pure is_logged_in.
    pub is_logged_in: bool,
    pub is_trading_account: bool,
    pub order_type: EventOrderType,
    pub price_input: EventPriceInputConfig,
    pub amount_input: EventAmountInputConfig,
    /// Editable Total (cost) input — three-way price/amount/total linkage
    /// (PRD #6). `value` is user-typed on the reverse path (Total → Amount) and
    /// Rust-written on the forward path (price/amount → Total). Present only for
    /// buy + limit (mirror Native `getCostInputComponent()`); RenderExt projects
    /// `value`/`unit` and does the byte-exact controlled write-back guard
    /// (rust-pure-input-srp). Cleared immediately when price/amount change
    /// (`on_price_changed`/`on_amount_changed`) so a stale Total never lingers.
    pub total_input: EventTotalInputConfig,
    /// Some(_) ⇔ amount is seekbar-driven and recomputed on side/direction/
    /// max_avail changes (0-1 decimal form). Cleared by typed input.
    pub seekbar_percent: Option<String>,
    /// UI-ready seekbar cover text ("50%" / "25%" / …). Rust owns the
    /// formatting (A2 — mirror V1 `OKTNumberF.formatPercent(percent, 0, UP)`)
    /// so Kotlin `RenderExt` reads a `DisplayString` and drops the OKTradeCore
    /// `OKTNumberF` dependency. Derived from `seekbar_percent` in `reproject_into`;
    /// `None` when the seekbar is not owner (typed / cleared).
    pub seekbar_percent_display: Option<DisplayString>,
    pub panel_visibility: EventPanelVisibilityVo,
    pub btn_config: EventBuySellBtnConfig,
    pub cost: EventCostState,
    pub validation_error: OktEventValidationError,
    pub max_avail: OktEventMaxAvailState,
    pub pre_check: OktEventPreCheckState,
    pub order_result: OktEventOrderResult,
    pub is_placing_order: bool,
    pub order_snapshot: Option<OktEventOrderInputSnapshot>,
    pub last_price: String,
    /// One-shot flag guarding the "seed last price into empty price_input"
    /// path (L1 — quick order Limit tab). Native
    /// `EventQuickOrderLimitPresenter.applyLastPriceToInput:104-115` fills the
    /// price input with the ticker last price (or `1 - price` for outcome=NO)
    /// only when the input is still empty — the user's typed value must never
    /// be overwritten. Rust flips this to `true` after the first successful
    /// seed so subsequent ticker pushes don't clobber user input.
    pub price_seeded_from_last_price: bool,
}

