/// Pure MarginLimit state (STEP2 shell). Partition layout mirrors
/// `PureSpotLimitState`; margin deltas applied per PORT_MAP §1.
#[derive(Debug, Clone, PartialEq)]
pub struct PureMarginLimitState {
    /// Whether this mounted panel currently owns its exact applied scope.
    pub is_submit_ready: bool,
    pub load_state: PureLoadState,
    pub inst_id: String,
    pub instrument: Option<PureOKTSpotInstrumentSnapshot>,
    pub source: PureEntrySource,
    pub follows_main_page: bool,
    pub is_quick_order: bool,
    pub price: String,
    pub amount: String,
    pub probably_value: String,
    pub side: OKTSpotSide,
    pub dirty_source: PureDirtySource,
    /// One-shot guard for the ticker-driven initial price seed. The continuous
    /// ticker loop seeds `price` from `ticker.last` only while this is false AND
    /// the box is empty; it flips true after the first seed OR after any user
    /// price edit (`on_price_changed`, incl. clearing). Reset to false on
    /// instrument change so the new instrument gets one fresh seed. This
    /// distinguishes "never seeded" from "user cleared" — `price.is_empty()`
    /// alone cannot, so a cleared price was re-filled on the next tick (F).
    /// Spot-limit avoids this by seeding only at discrete lifecycle points
    /// (`prefill_price_from_ticker`), never inside the continuous ticker loop.
    pub price_seeded_from_ticker: bool,
    pub price_input_config: PurePriceInputConfig,
    pub amount_input_config: PureAmountInputConfig,
    pub total_input_config: PureTotalInputConfig,
    /// Canonical UI-ready projection shared by full/quick and all Native clients.
    pub presentation: PureMarginOrderPresentation,
    pub buy_button_text: String,
    pub sell_button_text: String,
    pub displayed_avail_balance: PureDisplayedAvailBalance,
    pub price_tick_misaligned: bool,
    pub amount_lot_misaligned: bool,
    pub validation_error: Option<PureValidationError>,
    pub is_place_btn_enabled: bool,
    pub est_total_value: String,
    pub is_est_total_value_loaded: bool,
    /// Soft-keyboard "min order amount" hint value, denominated in quote_ccy.
    pub min_order_amount_value: String,
    pub is_min_order_amount_value_loaded: bool,
    /// MARGIN DELTA — resolved trade mode is `OktMarginTdMode` (isolated/cross).
    pub resolved_td_mode: OktMarginTdMode,
    pub is_trade_borrow_mode: bool,
    pub can_borrow: bool,
    pub is_side_support_loan: bool,
    pub supports_available_transfer: bool,
    /// V1 `TradeCommonUtils.isPmUnique()` — true only when the account is
    /// pure-PM (portfolio margin only). Mirror of spot's `is_pm_unique`
    /// field. Margin's `amount_percent_visible` derive reads this to GONE the
    /// amount-percent seekbar for PM-unique accounts (V1
    /// `MarginLimitTradePanelPresenter.kt:765-775`).
    /// 
    /// EMIT_PENDING(T-PM-UNIQUE-FLAG-PORT) — REUSED from spot's Stage-1
    /// blocker: the canonical `AccountConfigGetter::is_pm_unique` has not been
    /// audited for UniFFI exposure yet, so no producer is wired in Stage-1
    /// (spot only resets it to `false` in `on_user_changed`; there is no
    /// canonical setter to mirror). Default = false. Tracked under
    /// R-MIG-35 EMIT_PENDING ticket T-PM-UNIQUE-FLAG-PORT (same as spot).
    pub is_pm_unique: bool,
    /// V1 `CollateralCoinUtils.getCollateralCoinBtnVisibility(...)` — whether
    /// the open-collateral-coin button is visible. Mirror of spot's
    /// `is_collateral_coin_btn_visible` field. Producer:
    /// `orchestration::collateral::derive_is_collateral_coin_btn_visible`
    /// (re-run inside `recompute_collateral_derives`). The margin
    /// `init_lend_amount_visible` derive ANDs in `!is_collateral_coin_btn_visible`
    /// (V1 `AbsMarginTradePanelPresenter.kt:541-544`).
    pub is_collateral_coin_btn_visible: bool,
    /// Whether the active max-buy/max-sell label exposes the best-leverage help
    /// affordance. Written by the best-leverage query; false for reduce-only,
    /// collateral-limit instruments, missing data, and failed requests.
    pub show_max_leverage_help: bool,
    pub max_trade_affordance: OktMaxTradeAffordance,
    pub max_trade_base_restricted: bool,
    pub max_trade_quote_restricted: bool,
    pub collateral_limit_reduce_only: bool,
    pub td_mode: OKTSpotTdMode,
    /// Panel leverage as a display String (e.g. "5" / "1.1"). String not u32:
    /// margin leverage can be fractional (header keeps up to 2 decimals), which
    /// u32 could not represent — the confirm sheet showed the stale biz value
    /// when the live leverage was fractional. Also parsed to Decimal in confirm.
    pub leverage: String,
    pub is_order_confirm_open: bool,
    pub seekbar_percent: Option<u32>,
    pub strategy_type: PureStrategyType,
    pub market_type: PureMarketType,
    pub trade_quote_ccy: String,
    pub trade_quote_ccy_list: Vec<String>,
    /// Margin currency. Server returns 50014 if missing on submit.
    pub ccy: Option<String>,
    /// Reduce-only order flag.
    pub reduce_only: bool,
    /// 100%-percent full quantity applicable.
    pub is_full_percent: bool,
    pub tpsl_config: Option<PureTpslConfig>,
    pub tpsl_validation_error: Option<PureTpslValidationError>,
    pub is_tpsl_supported: bool,
    pub ticker_display_digit: u32,
    pub change_percent_digit: u32,
    pub max_avail: PureMaxAvailState,
    /// Reduce-only basis that produced `max_avail`. It intentionally trails
    /// `reduce_only` while a keyed refresh is in flight so old response values
    /// are never formatted with the new checkbox currency basis.
    pub max_avail_reduce_only: bool,
    pub pre_check: PurePreCheckState,
    /// Raw pre-check resp snapshot from the LAST successful `precheck_order`
    /// call. Producer: `precheck_order` action (interactor) — written from the
    /// `OrderPreCheckResp` returned by `LimitOrderManager::pre_check_order` on
    /// `is_success`. Consumer: `orchestration::confirm::b016_get_order_confirm_data`
    /// — the margin MMR / before-after / cost confirm rows are sourced from
    /// THIS field (server convention), NOT the local `calculate_margin_mode_margin_info`
    /// guess. `None` until the first successful precheck (b016 then falls back
    /// to the local cost guess for backward compat).
    pub precheck_resp: Option<PureMarginPreCheckSnapshot>,
    pub order_result: PureOrderResult,
    /// Latest traded price (`ticker.last`) for the current instrument.
    pub last_price: Option<String>,
    pub price_bubble: PurePriceBubble,
    /// Quote-currency/USD ticker used by the Native-compatible price valuation.
    pub quote_ticker_last: String,
    /// Native-owned focus signal; all value/visibility derivation remains in Rust.
    pub is_price_input_focused: bool,
    /// USD-to-current-local-fiat rate, sourced from CurrencyRateManager.
    pub usd_to_local_rate: String,
    /// Current local-fiat symbol, sourced from CurrencyRateManager.
    pub local_fiat_symbol: String,
    /// Monotonic token for the visible bubble presentation. Native timers must
    /// echo this value when requesting a hide so an older timer cannot hide a
    /// newer price/ticker/rate projection.
    pub price_bubble_revision: u64,
    pub is_logged_in: bool,
    pub region: PureRegion,
    pub feature_flags: PureFeatureFlags,
    pub spot_available_cache: HashMap<String, bool>,
}

