#[derive(Debug, Clone, PartialEq)]
pub struct StrategyOrderAmtData {
    /// Conditional/OCO order count
    pub stop_amt: String,
    /// Trigger order count
    pub trigger_amt: String,
    /// Trailing stop (move order stop) count
    pub move_stop_amt: String,
}

