/// OCO child interactor state (flat P1a stage — mirrors monolith field names).
#[derive(Debug, Clone, PartialEq)]
pub struct TrailingTpslState {
    /// Session-sourced contract meta (precision / unit / ccy) — §2.8 /
    /// R-MIG-196. Projected from the parent `TradeSessionContext`, not relayed.
    pub inst_meta: Option<ContractInstMeta>,
    /// Instrument id (e.g. "BTC-USDT-SWAP").
    pub inst_id: String,
    /// Instrument type (SWAP / FUTURES …) — drives `source_contract_inst_meta`.
    pub inst_type: String,
    /// "BUY" / "SELL".
    pub side: String,
    /// Leverage hint.
    pub lever: String,
    /// Entrust (order) price — mother-order price for PnL / reverse compute.
    pub entrust_price: String,
    /// Entrust (order) size.
    pub entrust_size: String,
    /// Latest market price (parent session subscription → broadcast).
    pub latest_price: String,
    /// Latest mark price (parent session subscription -> broadcast).
    pub mark_price: String,
    /// Latest index price (parent session subscription -> broadcast).
    pub index_price: String,
    /// TPSL submit mode echoed in the `Confirm` payload.
    pub tpsl_mode: PureTpslMode,
    /// Always false for this OCO-only child (moved use_case guard parity).
    pub is_multi_mode: bool,
    /// Always false for this OCO-only child (moved use_case guard parity).
    pub is_trailing_mode: bool,
    /// Callback-variance mode: Percentage (ratio) / Constant (price-spread).
    pub variance_type: OktTrailingVarianceType,
    /// Raw callback-variance input (display domain, e.g. "5" for 5%).
    pub variance_value: String,
    /// Monotonic input-revision counter — bumped on EVERY `on_variance_value_changed`
    /// so a clamp-to-same-max still produces an observable state change, forcing the
    /// controlled render echo (else `modify_state` dedup swallows the notify → render
    /// → echo, leaving the raw over-max text in the box). Mirrors
    /// `AdjustLeverPageState.input_revision` (clamp-back-same-value no-repaint lesson).
    /// Not read by Kotlin directly.
    pub input_revision: u64,
    /// Raw activation price input.
    pub activation_px: String,
    /// Whether the activation-price row is enabled.
    pub activation_px_enabled: bool,
    /// Inline variance validation error (CDKey-resolved message).
    pub variance_error: Option<String>,
    /// Inline activation-price validation error.
    pub activation_error: Option<String>,
    /// Decimal places for price/spread inputs (from instrument).
    pub price_digit: u32,
    /// Instrument tick size (variance/activation step align).
    pub tick_size: String,
    /// Min callback ratio (display domain, e.g. "0.1").
    pub ratio_min: String,
    /// Max callback ratio (display domain, e.g. "5").
    pub ratio_max: String,
    /// Max value for the price-distance (Constant) variance box = the latest
    /// market price in the DISPLAY unit (base->display, inverse-aware). Rust clamps
    /// entries above it in `on_variance_value_changed` (SSoT-owned, NOT the Kotlin
    /// widget), mirroring native `ContractTrailingStopFragment` `setMaxValue(lastShowPx)`.
    /// Empty when `latest_price` is empty / <= 0 (skip the clamp = native
    /// `setMaxValue(null)` no-op). Percentage mode uses `ratio_max` instead.
    pub spread_max: String,
    /// Quote-ccy unit for constant variance + activation display (e.g. "USDT").
    pub price_symbol: String,
    /// Overall trailing-form validity (variance + activation).
    pub is_valid: bool,
    /// Whether any trailing data is present (variance or activation).
    pub is_data_present: bool,
    /// Amend-order flow flag.
    pub is_amend: bool,
    /// Formatted variance (Percent / value+symbol); Placeholder when empty.
    pub variance_display: DisplayString,
    /// Formatted activation price (value+symbol); Placeholder when empty.
    pub activation_display: DisplayString,
    /// Description block visibility (variance present).
    pub desc_visible: bool,
    /// 1-paragraph description (activation off).
    pub desc_single: DisplayString,
    /// 2-step description, step 1 (activation on).
    pub desc_step1: DisplayString,
    /// 2-step description, step 2 (activation on).
    pub desc_step2: DisplayString,
    pub tp_trigger_price: String,
    pub tp_change_pct: String,
    pub tp_is_limit: bool,
    pub tp_limit_price: String,
    pub tp_trigger_px_type: PureTriggerPxType,
    pub tp_dynamic_trigger_px: String,
    pub tp_strategy_kind: Option<PureAttachedTpslStrategyKind>,
    pub tp_profit: String,
    pub tp_reverse_trigger_display: DisplayString,
    pub tp_pnl_display: DisplayString,
    pub tp_tip_display: DisplayString,
    pub tp_trigger_px_type_display: DisplayString,
    pub tp_income_type_label: DisplayString,
    pub tp_income_type_unit: String,
    pub tp_section_config: PureContractOcoSectionConfig,
    pub tp_trigger_input: ContractPriceInputConfig,
    pub tp_limit_px_input: ContractPriceInputConfig,
    pub tp_type_value_input: TpslTypeValueInputConfig,
    pub sl_trigger_price: String,
    pub sl_change_pct: String,
    pub sl_is_limit: bool,
    pub sl_limit_price: String,
    pub sl_trigger_px_type: PureTriggerPxType,
    /// True after an authoritative user/config seed writes the trigger source.
    /// Remembered defaults may only fill the type while this remains false.
    pub sl_trigger_px_type_is_explicit: bool,
    pub sl_dynamic_trigger_px: String,
    pub sl_strategy_kind: Option<PureAttachedTpslStrategyKind>,
    /// Persisted amend ratio used to preserve the locked dynamic selector.
    pub sl_original_trigger_ratio: String,
    /// SL income kind lock (mirror OCO `oco_locked_income_kind`). `Some(kind)` =
    /// income selector disabled + kind forced. Set to `Some(ByPrice)` on amend
    /// (V1 `FROM_ONGOING_ORDER` parity, UniSetTpSlView.kt:842). Default None.
    pub sl_locked_income_kind: Option<PureAttachedTpslStrategyKind>,
    pub sl_profit: String,
    pub sl_reverse_trigger_display: DisplayString,
    pub sl_pnl_display: DisplayString,
    pub sl_tip_display: DisplayString,
    pub sl_trigger_px_type_display: DisplayString,
    pub sl_income_type_label: DisplayString,
    pub sl_income_type_unit: String,
    pub sl_section_config: PureContractOcoSectionConfig,
    pub sl_trigger_input: ContractPriceInputConfig,
    pub sl_limit_px_input: ContractPriceInputConfig,
    pub sl_type_value_input: TpslTypeValueInputConfig,
    /// OCO cross-leg validator result (pushed in by Kotlin).
    pub validation_legal: bool,
    /// Validation event code → `ShowValidationDialog` on illegal confirm.
    pub validation_event_code: String,
    /// Inline SL price-relationship validation error (confirm-time, 4.2
    /// DisplayString). Set by `on_trailing_confirm`'s shared `compute_sl_verdict`
    /// hard-block; cleared on SL edit (recompute) and on a clean confirm.
    pub sl_validation_error: DisplayString,
    /// BY_PROFIT picker "PnL ({ccy})" currency symbol (Bug4a; Rust-derived).
    pub profit_ccy_symbol: String,
    /// Last-seen parent `clear_revision`; reset inputs when ctx differs (dedupe).
    pub seen_clear_revision: u64,
}

